const fn compute_cache_construction_bytes() -> Option<usize> {
    sum_named!(&[
        (3, size_of::<Result<Option<WasiUsage>, SwiftRunFailure>>()),
        (3, size_of::<Option<Result<WasiUsage, SwiftRunFailure>>>()),
        (3, size_of::<Result<WasiUsage, SwiftRunFailure>>()),
        (
