        partial.patches.push(decode::EMPTY_PATCH);
    }
    reserve(&mut partial.index, RESIDENT_INDEX_CELLS, &mut self.control)?;
    for _ in 0..RESIDENT_INDEX_CELLS {
        self.control.work(1)?;
        partial.index.push(0);
    }
